-- 028: parks and coasters for a second rider's ranking sheet (2026-10-04).
-- Carter sent "Roller_Coaster_Ranking.xlsx" (341 ranked rides, mostly Germany,
-- Austria, Benelux, Italy, Poland and French/German travelling fairs):
-- "Another please".
--
-- Matched against the live tables after 027. Before this, 153 rows had no
-- match: 126 at 54 parks we lacked, the rest at parks we have. After it, every
-- park matches, and the 11 rows left are spellings /import already resolves
-- or asks about ("Max & Moritz (Max)", "Dawson Duel (left)" against our
-- Blue/Green, "le Twist").
--
-- Unlike 027's sheet this one carries no maker or model, so those are filled
-- only where certain (iSpeed, Katun, Star Trek, Falcon, Thundercoaster …) and
-- left blank otherwise for /edit. Same for opening years. Pins for parks with
-- a fixed address; travelling showmen as "<Name> (travelling)", as in 027.
-- Some of the sheet's park names are other names for parks we have (Kolmården
-- Zoo, Ferrari World Abu Dhabi, Plopsaland Ardennes = Plopsa Coo, plain
-- "Barth"/"Eberhard" for 027's showmen) and go in as park aliases.
--
-- Safe to run twice; the same name (+ park) checks as 027. Dry run against
-- the live tables: parks 340 -> 384, coasters 1470 -> 1593; a second run
-- changed nothing. Raw SQL skips the Worker, so run Actions -> "Sync static
-- JSON from D1" after.
--
-- From a phone, paste migrations/028-paste/part-N.sql in order.
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Desmo Race Destra', 'import 028', date('now') FROM coasters WHERE name = 'Desmo Race (Destra)' AND park = 'Mirabilandia';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Desmo Race Sinistra', 'import 028', date('now') FROM coasters WHERE name = 'Desmo Race (Sinistra)' AND park = 'Mirabilandia';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Demo Race Sinistra', 'import 028', date('now') FROM coasters WHERE name = 'Desmo Race (Sinistra)' AND park = 'Mirabilandia';
